// TypeScript Version: 4.1

/**
* Interface describing a results object.
*/
interface Results {
	/**
	* Number of times the data was clustered with different initial centroids.
	*/
	replicates: number;

	/**
	* Index of the initial centroids which produced the best result.
	*/
	replicate: number;

	/**
	* Distance metric.
	*/
	metric: string;

	/**
	* Number of iterations for best results.
	*/
	iterations: number;

	/**
	* Clustering algorithm.
	*/
	algorithm: string;

	/**
	* Sum of squared distances to the closest centroid for all samples.
	*/
	inertia: number;

	/**
	* Number of clusters.
	*/
	k: number;

	/**
	* Number of samples.
	*/
	samples: number;

	/**
	* Number of features.
	*/
	features: number;

	/**
	* Clustering method.
	*/
	method: string;
}

/**
* Serializes a k-means clustering results object as a JSON object.
*
* @param results - k-means clustering results object
* @returns serialized object
*
* @example
*
* var results = {
*     'replicates': 4,
*     'replicate': 2,
*     'metric': 'sqeuclidean',
*     'iterations': 10,
*     'algorithm': 'lloyd',
*     'inertia': 3.28,
*     'k': 4,
*     'samples': 10,
*     'features': 3,
*     'method': 'K-means clustering'
* };
*
* var obj = res2json( results );
* // returns {...}
*/
declare function res2json( results: Results ): Results;


// EXPORTS //

export = res2json;
